/* Accueil des visiteurs non connectés (vue « Accueil » de l'appli, Belgique, en français).
   Monté par index.html (renderHome) dans un shadow DOM : ses styles ne touchent pas au reste du site,
   l'en-tête (nav#main-nav) et le pied de page restent ceux de l'appli.
   Les boutons passent par la navigation de l'appli (go(), openAuth()). Source de travail : maquettes/accueil-vitrine.html. */
(function(){
var CSS="\n/* Page d'accueil des visiteurs non connectés (keypace.be). Les élèves et profs connectés vont sur /accueil.\n   Source de travail : maquettes/accueil-vitrine.html. */\n:host{display:block;--accent:#FF4D2E;--accent2:#FF8A3D;--bg:#FAF9F5;--card:#fff;--border:#E7E1D5;--txt:#16140F;--muted:#716A5E;--light:#F4F1EA;--violet:#6D5DF5;--blue:#2F7DF6;--green:#1FA971}\n*{box-sizing:border-box;margin:0;padding:0}\n.lp{background:var(--bg);color:var(--txt);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,Roboto,sans-serif;font-size:17px;line-height:1.55;-webkit-font-smoothing:antialiased;overflow-x:clip}\na{color:inherit;text-decoration:none}\nbutton{font-family:inherit;cursor:pointer}\nimg{max-width:100%}\n.wrap{max-width:1200px;margin:0 auto;padding:0 28px}\n@media(max-width:700px){.wrap{padding:0 16px}}\nh1,h2,h3,h4{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;letter-spacing:-.03em}\n.eyebrow{font:700 12px 'JetBrains Mono',monospace;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}\n\n/* ---------- Nav ---------- */\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:12px;padding:14px 22px;font-weight:700;font-size:15.5px;border:1.5px solid transparent;transition:transform .15s,background .15s,box-shadow .15s;white-space:nowrap}\n.btn:hover{transform:translateY(-1px)}\n.btn-accent{background:var(--accent);color:#fff;box-shadow:0 0 0 4px rgba(255,77,46,.14),0 12px 24px -12px rgba(255,77,46,.8)}\n.btn-ghost{background:#fff;border-color:var(--border);color:var(--txt)}.btn-ghost:hover{border-color:#D6CCBB}\n.btn-sm{padding:8px 14px;font-size:14px;border-radius:10px}\n\n/* ---------- Héros ---------- */\n.hero{position:relative;padding:90px 0 48px;text-align:center}\n.hero::before{content:'';position:absolute;left:50%;top:-320px;width:1100px;max-width:100vw;height:700px;transform:translateX(-50%);background:radial-gradient(closest-side,rgba(255,138,61,.28),rgba(255,77,46,.06) 60%,transparent);pointer-events:none}\n.kicker{position:relative;display:inline-flex;gap:10px;align-items:center;font:500 13px 'JetBrains Mono',monospace;color:#5F584D;border:1px solid var(--border);border-radius:30px;padding:6px 14px 6px 6px;background:#fff}\n.kicker b{background:var(--accent);color:#fff;border-radius:20px;padding:2px 9px;font-weight:700}\nh1{position:relative;font-size:clamp(42px,6.4vw,88px);line-height:.98;margin:26px auto 22px;max-width:1000px}\nh1 .k{display:inline-block;font:700 .62em 'JetBrains Mono',monospace;color:var(--accent);background:#FFEDE7;border:1.5px solid #FFC7B8;border-radius:.25em;padding:.02em .22em;vertical-align:.12em;letter-spacing:0;box-shadow:0 .08em 0 #FFC7B8}\n.lead{position:relative;font-size:20px;color:var(--muted);max-width:680px;margin:0 auto}\n.hero-cta{position:relative;display:flex;gap:12px;justify-content:center;margin-top:32px;flex-wrap:wrap}\n@media(max-width:700px){.hero{padding:56px 0 0}.hero-cta .btn{width:100%}}\n\n/* ---------- Immersion : les quatre piliers ---------- */\n.immerse{position:relative}\n.stage{padding:56px 0 90px}\n.im-head{position:relative;text-align:center;margin-bottom:56px}\n.im-titles{position:relative;height:clamp(46px,5vw,68px);margin:12px 0 22px}\n.im-titles h2{position:absolute;inset:0;font-size:clamp(34px,4.6vw,60px);line-height:1.05;opacity:0;transform:translateY(26px);transition:opacity .45s,transform .45s cubic-bezier(.2,.8,.2,1)}\n.im-titles h2.on{opacity:1;transform:none}\n.im-titles h2 span{color:var(--c,var(--accent))}\n.im-steps{display:inline-flex;gap:6px;background:#fff;border:1px solid var(--border);border-radius:30px;padding:5px}\n.im-steps b{font:700 12px 'JetBrains Mono',monospace;color:#B2A999;padding:6px 12px;border-radius:20px;transition:background .35s,color .35s}\n.im-steps b.done{color:var(--txt)}\n.im-steps b.on{background:var(--c);color:#fff}\n.im-grid{position:relative;display:grid;grid-template-columns:repeat(4,1fr);gap:20px}\n.spot{position:absolute;top:50%;left:12%;width:440px;height:440px;border-radius:50%;transform:translate(-50%,-50%);filter:blur(80px);opacity:0;z-index:0;pointer-events:none;transition:left .7s cubic-bezier(.2,.8,.2,1),background-color .7s,opacity .6s}\n.slot{position:relative;z-index:1;will-change:transform,opacity}\n\n.pc{position:relative;height:100%;background:#fff;border:1.5px solid var(--border);border-radius:24px;overflow:hidden;display:flex;flex-direction:column;transition:transform .55s cubic-bezier(.2,.8,.2,1),opacity .45s,filter .45s,border-color .35s,box-shadow .45s}\n.pc-vis{position:relative;height:230px;background:var(--tint);overflow:hidden}\n.pc-body{padding:20px 22px 22px;display:flex;flex-direction:column;gap:6px;flex:1}\n.pc-lab{align-self:flex-start;font:700 11.5px 'JetBrains Mono',monospace;letter-spacing:.14em;text-transform:uppercase;color:var(--c);border-radius:20px;transition:background .35s,color .35s,padding .35s}\n.pc-num{font:800 40px/1 'JetBrains Mono',monospace;letter-spacing:-.04em;margin-top:4px}\n.pc-num small{font-size:15px;letter-spacing:0;color:var(--muted);font-weight:600;margin-left:6px}\n.pc h3{font-size:21px;line-height:1.15;margin-top:4px}\n.pc p{color:var(--muted);font-size:14.5px;flex:1}\n.pc .go{font-weight:700;font-size:14.5px;color:var(--c);margin-top:8px}\n.pc .go::after{content:' →';display:inline-block;transition:transform .2s}.pc:hover .go::after{transform:translateX(4px)}\n/* Focus appuyé : la carte active se soulève, prend sa couleur, les autres s'effacent */\n.pc.focus{transform:translateY(-18px) scale(1.06);border:2px solid var(--c);box-shadow:0 44px 70px -30px color-mix(in srgb,var(--c) 70%,transparent),0 0 0 7px color-mix(in srgb,var(--c) 14%,transparent)}\n.pc.focus .pc-lab{background:var(--c);color:#fff;padding:4px 10px}\n.pc.dim{opacity:.32;filter:grayscale(.85) blur(1px);transform:scale(.94)}\n\n/* Mode épinglé (grand écran) */\n.immerse.pinned{height:320vh}\n.immerse.pinned .stage{position:sticky;top:var(--nav-h,0px);height:calc(100vh - var(--nav-h,0px));display:flex;flex-direction:column;justify-content:flex-start;padding:clamp(28px,6vh,64px) 0 0}\n@media(max-height:860px){.immerse.pinned .pc-vis{height:180px}.immerse.pinned .im-head{margin-bottom:46px}.immerse.pinned .im-titles{margin:8px 0 14px}.immerse.pinned .pc-body{padding:16px 20px 18px}.immerse.pinned .pc-num{font-size:34px}}\n@media(max-height:740px){.immerse.pinned .pc p{display:none}.immerse.pinned .pc-vis{height:160px}}\n/* Mode simple (mobile, mouvement réduit) */\n.immerse:not(.pinned) .slot{opacity:0;transform:translateY(50px) scale(.96);transition:opacity .7s,transform .7s cubic-bezier(.2,.8,.2,1)}\n.immerse:not(.pinned) .slot.in{opacity:1;transform:none}\n.immerse:not(.pinned) .im-steps,.immerse:not(.pinned) .spot{display:none}\n@media(max-width:959px){.im-grid{grid-template-columns:1fr 1fr}}\n@media(max-width:620px){.im-grid{grid-template-columns:1fr}.pc-vis{height:210px}}\n@media(prefers-reduced-motion:reduce){.immerse:not(.pinned) .slot{opacity:1;transform:none;transition:none}}\n\n/* Visuel 1 : clavier qui s'allume */\n.v-kb{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px}\n.v-kb .word{font:800 26px 'JetBrains Mono',monospace;letter-spacing:.06em;color:#E7C9BC;height:32px}\n.v-kb .word .ok{color:var(--txt)}\n.kb{display:flex;flex-direction:column;gap:5px;align-items:center}\n.kb div{display:flex;gap:4px}\n.kb div:nth-child(2){margin-left:10px}.kb div:nth-child(3){margin-left:-14px}\n.kb span{width:20px;height:22px;border-radius:5px;background:#fff;box-shadow:0 2px 0 #EBD6CB;display:grid;place-items:center;font:700 9.5px 'JetBrains Mono',monospace;color:#B9A79C;transition:background .12s,color .12s,transform .12s}\n.kb span.home{color:var(--txt)}\n.kb span.hit{background:var(--accent);color:#fff;transform:translateY(2px);box-shadow:0 0 0 #fff}\n.v-kb .lesson{display:flex;align-items:center;gap:10px;font:700 11px 'JetBrains Mono',monospace;color:var(--muted)}\n.v-kb .lesson i{width:110px;height:6px;border-radius:6px;background:#F3DDD3;overflow:hidden}\n.v-kb .lesson i em{display:block;height:100%;width:18%;background:var(--accent);border-radius:6px;transition:width .6s}\n/* Visuel 2 : mots qui tombent */\n.v-fall{position:absolute;inset:0}\n.v-fall .w{position:absolute;top:-24px;font:700 14px 'JetBrains Mono',monospace;background:#fff;border-radius:8px;padding:4px 9px;box-shadow:0 4px 12px -4px rgba(60,40,140,.25);color:var(--txt)}\n.live .v-fall .w{animation:fall 4.2s linear infinite}\n@keyframes fall{0%{transform:translateY(0);opacity:0}8%{opacity:1}62%{transform:translateY(150px);background:#fff;color:var(--txt)}66%{transform:translateY(150px) scale(1.12);background:var(--violet);color:#fff}80%{transform:translateY(150px) scale(1.5);opacity:0}100%{opacity:0;transform:translateY(150px)}}\n.v-fall .ground{position:absolute;left:14px;right:14px;bottom:18px;display:flex;justify-content:space-between;align-items:center;font:700 11px 'JetBrains Mono',monospace;color:#6E66A8}\n.v-fall .ground b{font-size:15px;color:var(--violet)}\n.v-fall .bar{position:absolute;left:14px;right:14px;bottom:44px;height:2px;background:repeating-linear-gradient(90deg,#CFC8F5 0 6px,transparent 6px 12px)}\n/* Visuel 3 : un mail qui s'écrit */\n.v-mail{position:absolute;left:18px;right:18px;top:16px;bottom:46px;overflow:hidden;background:#fff;border-radius:14px;box-shadow:0 14px 30px -12px rgba(30,70,160,.3);padding:12px 14px;font-size:12px}\n.v-mail .dots{display:flex;gap:5px;margin-bottom:6px}.v-mail .dots i{width:8px;height:8px;border-radius:50%;background:#E3E8F2}\n.v-mail .f{display:flex;gap:6px;border-bottom:1px solid #EEF1F6;padding:3px 0;font-size:11.5px;color:#7B8396}\n.v-mail .f b{color:var(--txt);font-weight:600}\n.v-mail .body{padding-top:6px;font-size:11.5px;line-height:1.55;color:var(--txt)}\n.v-mail .body .cur{display:inline-block;width:1.5px;height:13px;background:var(--blue);vertical-align:-2px;animation:blink 1s steps(1) infinite}\n@keyframes blink{50%{opacity:0}}\n.v-chips{position:absolute;left:0;right:0;bottom:14px;display:flex;justify-content:center;gap:6px}\n.v-chips span{font-size:11px;font-weight:700;border-radius:20px;padding:4px 9px;background:#EAF2FF;color:#2F5FB8;opacity:.45;transition:opacity .3s,background .3s,color .3s}\n.v-chips span.on{opacity:1;background:var(--blue);color:#fff}\n/* Visuel 4 : courbe de progrès */\n.v-prog{position:absolute;inset:0;padding:18px}\n.v-prog .top{display:flex;justify-content:space-between;align-items:flex-start}\n.v-prog .wpm{font:800 34px/1 'JetBrains Mono',monospace;color:var(--txt)}\n.v-prog .wpm small{display:block;font-size:10.5px;color:var(--muted);font-weight:700;letter-spacing:.06em;margin-top:4px}\n.v-prog .badge{font:800 12px 'JetBrains Mono',monospace;background:var(--green);color:#fff;border-radius:20px;padding:5px 10px;opacity:0;transform:scale(.6);transition:opacity .3s,transform .4s cubic-bezier(.3,1.6,.5,1)}\n.v-prog .badge.on{opacity:1;transform:none}\n.v-prog svg{position:absolute;left:12px;right:12px;bottom:14px;width:calc(100% - 24px);height:120px;overflow:visible}\n.v-prog .grid line{stroke:#CDEBDD;stroke-dasharray:3 5}\n.v-prog .curve{fill:none;stroke:var(--green);stroke-width:3.5;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:420;stroke-dashoffset:420}\n.v-prog .area{fill:url(#gArea);opacity:0;transition:opacity .8s .6s}\n.v-prog.run .curve{transition:stroke-dashoffset 2.6s cubic-bezier(.4,0,.2,1);stroke-dashoffset:0}\n.v-prog.run .area{opacity:1}\n\n/* ---------- Bandeau des écoles : une rangée, défilement infini vers la droite ---------- */\n.trust{padding:24px 0 80px}\n.trust h2{text-align:center;font-size:clamp(26px,3.4vw,36px)}\n.trust p.sub{text-align:center;color:var(--muted);margin:6px auto 44px;max-width:56ch}\n.trust-mask{overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent);mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent)}\n.trust-row{display:flex;align-items:center;width:max-content;animation:toRight var(--dur,40s) linear infinite}\n.trust-mask:hover .trust-row{animation-play-state:paused}\n@keyframes toRight{from{transform:translate3d(-50%,0,0)}to{transform:translate3d(0,0,0)}}\n.logo-item{flex:none;height:40px;margin-right:64px;display:flex;align-items:center;filter:grayscale(1) contrast(.9) opacity(.55);mix-blend-mode:multiply;transition:filter .3s,transform .3s cubic-bezier(.2,.8,.3,1.3)}\n.logo-item:hover{filter:none;transform:scale(1.2)}\n.logo-item.tall{height:54px}\n.logo-item img{height:100%;width:auto;display:block}\n@media(prefers-reduced-motion:reduce){.trust-row{animation:none}}\n\n/* ---------- Et vous, vous êtes ? ---------- */\n.aud{padding:70px 0 100px}\n.sec-title{text-align:center;margin-bottom:30px}\n.sec-title h2{font-size:clamp(32px,4.4vw,58px);line-height:1.02}\n.sec-title p{color:var(--muted);margin-top:12px;font-size:18px}\n.tabs{display:flex;gap:4px;background:#fff;border:1px solid var(--border);border-radius:16px;padding:6px;width:max-content;max-width:100%;margin:0 auto 30px;overflow-x:auto}\n.tabs button{display:flex;align-items:center;gap:8px;background:none;border:none;color:var(--muted);font-weight:700;font-size:15px;padding:11px 18px;border-radius:11px;white-space:nowrap;transition:background .25s,color .25s}\n.tabs button i{width:9px;height:9px;border-radius:3px;background:var(--c);transition:background .25s}\n.tabs button:hover{color:var(--txt)}\n.tabs button.on{background:var(--c);color:#fff}\n.tabs button.on i{background:#fff}\n.panel{--pc:var(--accent);--pt:#FFF3EC;display:none;grid-template-columns:.95fr 1.05fr;gap:48px;align-items:center;background:#fff;border:1px solid var(--border);border-radius:32px;padding:48px;box-shadow:0 30px 60px -40px rgba(22,20,15,.25);position:relative;overflow:hidden}\n.panel::before{content:'';position:absolute;left:0;top:0;bottom:0;width:6px;background:var(--pc)}\n.panel.on{display:grid;animation:in .45s ease}\n@keyframes in{from{opacity:0;transform:translateY(12px)}}\n.p-tag{display:inline-flex;align-items:center;gap:8px;font:800 11.5px 'JetBrains Mono',monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--pc);background:var(--pt);border-radius:20px;padding:6px 12px;margin-bottom:16px}\n.panel h3{font-size:clamp(28px,3vw,40px);line-height:1.06;margin-bottom:14px}\n.panel p{color:#5F584D;font-size:17px;margin-bottom:22px}\n.panel ul{list-style:none;display:flex;flex-direction:column;gap:12px;margin-bottom:30px}\n.panel li{display:flex;gap:12px;align-items:flex-start;font-weight:600;font-size:16px}\n.panel li::before{content:'✓';flex-shrink:0;width:24px;height:24px;border-radius:8px;background:var(--pc);color:#fff;display:grid;place-items:center;font-size:13px;margin-top:-1px}\n.panel .acts{display:flex;gap:10px;flex-wrap:wrap}\n.btn-pc{background:var(--pc);color:#fff;box-shadow:0 5px 0 color-mix(in srgb,var(--pc) 70%,#000)}\n.btn-pc:hover{box-shadow:0 7px 0 color-mix(in srgb,var(--pc) 70%,#000);transform:translateY(-2px)}\n/* Scène visuelle à droite de chaque panneau */\n.viz{position:relative;min-height:420px;border-radius:24px;background:var(--pt);background-image:radial-gradient(color-mix(in srgb,var(--pc) 16%,transparent) 1.2px,transparent 1.2px);background-size:18px 18px;padding:28px}\n.shot{position:absolute;border-radius:14px;overflow:hidden;background:#fff;border:1px solid var(--border);box-shadow:0 30px 50px -24px rgba(22,20,15,.35)}\n.shot img{display:block;width:100%}\n.shot .bar{display:flex;gap:5px;padding:8px 10px;border-bottom:1px solid #F0EBE2;background:#FCFBF8}.shot .bar i{width:7px;height:7px;border-radius:50%;background:#E5DED2}\n.float{position:absolute;background:#fff;border-radius:16px;padding:12px 14px;box-shadow:0 18px 36px -16px rgba(22,20,15,.35);border:1px solid #F0EBE2;animation:fl 5s ease-in-out infinite}\n.float:nth-of-type(2n){animation-delay:-2.5s}\n@keyframes fl{50%{translate:0 -10px}}\n.float small{display:block;font:700 10.5px 'JetBrains Mono',monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.float b{font-family:'Bricolage Grotesque',sans-serif;font-size:16px}\n.big{font:800 30px/1 'JetBrains Mono',monospace;color:var(--pc)}\n.kiko{position:absolute;pointer-events:none;filter:drop-shadow(0 18px 20px rgba(0,0,0,.18))}\n.bubble{position:absolute;background:var(--txt);color:#fff;border-radius:14px;padding:8px 12px;font-weight:700;font-size:13px;white-space:nowrap}\n.bubble::after{content:'';position:absolute;left:18px;bottom:-7px;border:8px solid transparent;border-top-color:var(--txt);border-bottom:none}\n.dots-av{display:flex;margin-top:6px}.dots-av i{width:22px;height:22px;border-radius:50%;border:2px solid #fff;margin-left:-6px;display:grid;place-items:center;font:700 9px 'JetBrains Mono',monospace;color:#fff;font-style:normal}.dots-av i:first-child{margin-left:0}\n.xp{height:8px;border-radius:8px;background:#F3E3D8;overflow:hidden;margin-top:8px;width:150px}.xp span{display:block;height:100%;width:68%;border-radius:8px;background:linear-gradient(90deg,var(--accent2),var(--accent))}\n/* Établissement : maquette d'espace école */\n.school-ui{position:absolute;left:28px;right:28px;top:28px;background:#fff;border-radius:18px;border:1px solid var(--border);box-shadow:0 30px 50px -24px rgba(22,20,15,.3);overflow:hidden}\n.su-head{display:flex;align-items:center;gap:12px;padding:16px 18px;border-bottom:1px solid #F0EBE2}\n.su-head .ic{width:38px;height:38px;border-radius:11px;background:var(--pc);color:#fff;display:grid;place-items:center;font:800 15px 'JetBrains Mono',monospace}\n.su-head b{font-family:'Bricolage Grotesque',sans-serif;font-size:17px;display:block;line-height:1.1}\n.su-head span{font-size:12.5px;color:var(--muted)}\n.su-stats{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid #F0EBE2}\n.su-stats div{padding:12px 18px;border-right:1px solid #F0EBE2}.su-stats div:last-child{border:none}\n.su-stats b{display:block;font:800 22px 'JetBrains Mono',monospace}\n.su-stats span{font-size:12px;color:var(--muted)}\n.su-row{display:grid;grid-template-columns:1.1fr 1fr 70px;gap:12px;align-items:center;padding:11px 18px;border-bottom:1px solid #F5F1EA;font-size:13.5px}\n.su-row:last-child{border:none}\n.su-row b{font-weight:700}\n.su-row span{color:var(--muted);font-size:12.5px}\n.su-row .pb{height:6px;border-radius:6px;background:#EAF0FB;overflow:hidden}.su-row .pb i{display:block;height:100%;background:var(--pc);border-radius:6px}\n/* Partenaire : chiffres aux couleurs des piliers */\n.inv{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.inv div{background:#fff;border:1px solid var(--border);border-radius:18px;padding:20px;position:relative;overflow:hidden}\n.inv div::after{content:'';position:absolute;right:-18px;top:-18px;width:70px;height:70px;border-radius:50%;background:var(--ic);opacity:.12}\n.inv b{display:block;font:800 34px 'JetBrains Mono',monospace;color:var(--ic);letter-spacing:-.03em}\n.inv span{font-size:14px;color:#5F584D;font-weight:600}\n.pilots-mini{position:relative;margin-top:14px;background:#fff;border:1px solid var(--border);border-radius:18px;padding:16px 18px}\n.pilots-mini small{font:700 10.5px 'JetBrains Mono',monospace;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\n.pilots-mini div{display:flex;align-items:center;gap:18px;margin-top:10px;flex-wrap:wrap}\n.pilots-mini img{height:28px;width:auto;filter:grayscale(1);opacity:.7;mix-blend-mode:multiply}\n@media(max-width:900px){.panel{grid-template-columns:1fr;padding:30px 20px 24px 26px;gap:28px}.viz{min-height:360px;padding:18px}.school-ui{left:16px;right:16px;top:16px}}\n@media(max-width:520px){.su-row{grid-template-columns:1fr 70px}.su-row>span{display:none}.kiko{display:none}}\n\n/* ---------- Avis : bulles qui défilent, chaque auteur a sa mascotte ---------- */\n.rev{padding:30px 0 40px}\n.rev-head{display:flex;flex-direction:column;align-items:center;text-align:center;gap:14px;margin-bottom:20px}\n.rev-head h2{font-size:clamp(32px,4.4vw,58px);line-height:1.02}\n.rev-score{display:inline-flex;align-items:center;gap:14px;background:#fff;border:1px solid var(--border);border-radius:20px;padding:10px 18px 10px 12px;box-shadow:0 14px 30px -20px rgba(22,20,15,.3)}\n.rev-score b{font:800 30px/1 'JetBrains Mono',monospace;background:#FFF4DC;color:#B86E00;border-radius:12px;padding:8px 10px}\n.rev-score .st{color:#F5A623;font-size:20px;letter-spacing:2px;line-height:1}\n.rev-score small{display:block;font-size:13.5px;color:var(--muted);margin-top:3px}\n.rev-mask{overflow:hidden;padding:24px 0 30px;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}\n.rev-row{display:flex;align-items:flex-end;width:max-content;animation:toLeft var(--dur,80s) linear infinite}\n.rev-mask:hover .rev-row{animation-play-state:paused}\n@keyframes toLeft{from{transform:translate3d(0,0,0)}to{transform:translate3d(-50%,0,0)}}\n.rv{--c:var(--accent);--t:#FFF1EA;flex:none;width:340px;margin-right:26px;display:flex;flex-direction:column;transform:rotate(var(--r,0deg));transition:transform .35s cubic-bezier(.2,.8,.2,1)}\n.rv:hover{transform:rotate(0) translateY(-8px)}\n.rv-bubble{position:relative;background:#fff;border:2px solid var(--border);border-radius:24px;padding:22px 22px 20px;box-shadow:0 20px 40px -26px rgba(22,20,15,.35);transition:border-color .3s}\n.rv:hover .rv-bubble{border-color:var(--c)}\n.rv-bubble::before{content:'“';position:absolute;right:18px;top:-6px;font:800 84px/1 'Bricolage Grotesque',sans-serif;color:var(--c);opacity:.18}\n.rv-bubble::after{content:'';position:absolute;left:44px;bottom:-12px;width:22px;height:22px;background:#fff;border-right:2px solid var(--border);border-bottom:2px solid var(--border);transform:rotate(45deg);border-bottom-right-radius:5px;transition:border-color .3s}\n.rv:hover .rv-bubble::after{border-color:var(--c)}\n.rv-stars{color:#F5A623;font-size:16px;letter-spacing:2px}\n.rv-txt{font-family:'Bricolage Grotesque',sans-serif;font-weight:500;font-size:18px;line-height:1.35;letter-spacing:-.01em;margin-top:8px}\n.rv-foot{display:flex;align-items:flex-end;gap:12px;padding-left:16px;margin-top:4px}\n.rv-kiko{position:relative;width:84px;height:104px;flex:none;border-radius:0 0 20px 20px;overflow:visible}\n.rv-kiko::before{content:'';position:absolute;left:4px;right:4px;bottom:0;height:62px;border-radius:50%;background:var(--t)}\n.rv-kiko img{position:absolute;left:50%;bottom:0;height:124px;width:auto;max-width:none;transform:translateX(-50%);filter:drop-shadow(0 8px 8px rgba(0,0,0,.15));transform-origin:50% 100%}\n.rv:hover .rv-kiko img{animation:hop .6s cubic-bezier(.3,1.6,.5,1)}\n@keyframes hop{0%{transform:translateX(-50%)}40%{transform:translateX(-50%) translateY(-12px) rotate(-6deg)}100%{transform:translateX(-50%)}}\n.rv-who{padding-bottom:12px}\n.rv-who b{display:block;font-family:'Bricolage Grotesque',sans-serif;font-size:17px}\n.rv-who span{display:inline-flex;align-items:center;gap:6px;font:700 10.5px 'JetBrains Mono',monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--c);background:var(--t);border-radius:20px;padding:3px 9px;margin-top:3px}\n@media(max-width:600px){.rv{width:280px;margin-right:18px}.rv-txt{font-size:16.5px}}\n@media(prefers-reduced-motion:reduce){.rev-row{animation:none}.rev-mask{overflow-x:auto}}\n\n/* ---------- Final ---------- */\n.final{text-align:center;padding:120px 0;position:relative;overflow:hidden}\n.final::before{content:'';position:absolute;left:50%;bottom:-380px;width:1000px;max-width:100vw;height:600px;transform:translateX(-50%);background:radial-gradient(closest-side,rgba(255,138,61,.22),transparent);pointer-events:none}\n.final h2{position:relative;font-size:clamp(38px,5.6vw,76px);line-height:1;max-width:900px;margin:0 auto 30px}\n.final h2 span{color:var(--accent)}\n";
var HTML="<header class=\"hero\"><div class=\"wrap\">\n  <span class=\"kicker\"><b>Nouveau</b> Modules mail, CV et lettre de motivation</span>\n  <h1>La plateforme qui apprend le <span class=\"k\">clavier</span> et les bases du numérique.</h1>\n  <p class=\"lead\">Des cours de dactylographie AZERTY, des modules de compétences numériques, des jeux et un test de vitesse. Pour les élèves, et pour les écoles qui les accompagnent.</p>\n  <div class=\"hero-cta\"><a class=\"btn btn-accent\" href=\"/cours-dactylo-en-ligne\" data-cta=\"hero-commencer\">Commencer gratuitement</a><a class=\"btn btn-ghost\" href=\"/test\" data-cta=\"hero-test\">Tester ma vitesse</a><a class=\"btn btn-ghost\" href=\"/ecoles\" data-cta=\"hero-ecole\">Je représente une école</a></div>\n</div></header>\n\n<section class=\"immerse\" id=\"piliers\"><div class=\"stage\"><div class=\"wrap\">\n  <div class=\"im-head\">\n    <div class=\"eyebrow\">Ce que propose KeyPace</div>\n    <div class=\"im-titles\">\n      <h2 class=\"on\" style=\"--c:var(--accent)\">Apprendre à <span>taper</span>.</h2>\n      <h2 style=\"--c:var(--violet)\">S'entraîner en <span>jouant</span>.</h2>\n      <h2 style=\"--c:var(--blue)\">Maîtriser les <span>bases du numérique</span>.</h2>\n      <h2 style=\"--c:var(--green)\">Voir ses <span>progrès</span>.</h2>\n      <h2>Quatre piliers. <span>Une seule plateforme.</span></h2>\n    </div>\n    <div class=\"im-steps\"><b style=\"--c:var(--accent)\">01 Cours</b><b style=\"--c:var(--violet)\">02 Jeux</b><b style=\"--c:var(--blue)\">03 Compétences</b><b style=\"--c:var(--green)\">04 Progrès</b></div>\n  </div>\n\n  <div class=\"im-grid\">\n    <div class=\"spot\"></div>\n\n    <div class=\"slot\"><a class=\"pc\" href=\"/cours-dactylo-en-ligne\" data-cta=\"pilier-cours\" style=\"--c:var(--accent);--tint:#FFF1EA\" data-anim=\"kb\">\n      <div class=\"pc-vis\"><div class=\"v-kb\">\n        <div class=\"word\"></div>\n        <div class=\"kb\">\n          <div><span>A</span><span>Z</span><span>E</span><span>R</span><span>T</span><span>Y</span><span>U</span><span>I</span><span>O</span><span>P</span></div>\n          <div><span class=\"home\">Q</span><span class=\"home\">S</span><span class=\"home\">D</span><span class=\"home\">F</span><span>G</span><span>H</span><span class=\"home\">J</span><span class=\"home\">K</span><span class=\"home\">L</span><span class=\"home\">M</span></div>\n          <div><span>W</span><span>X</span><span>C</span><span>V</span><span>B</span><span>N</span></div>\n        </div>\n        <div class=\"lesson\">LEÇON <span class=\"ln\">12</span>/66 <i><em></em></i></div>\n      </div></div>\n      <div class=\"pc-body\"><span class=\"pc-lab\">01 · Cours</span><div class=\"pc-num\" data-to=\"66\">0<small>leçons</small></div><h3>Apprendre à taper sans regarder</h3><p>De la rangée de base aux symboles, accents et vrais mots français dès le départ.</p><span class=\"go\">Voir les cours</span></div>\n    </a></div>\n\n    <div class=\"slot\"><a class=\"pc\" href=\"/jeux-dactylo-en-ligne\" data-cta=\"pilier-jeux\" style=\"--c:var(--violet);--tint:#F0EEFF\" data-anim=\"fall\">\n      <div class=\"pc-vis\"><div class=\"v-fall\">\n        <span class=\"w\" style=\"left:12%;animation-delay:0s\">souris</span>\n        <span class=\"w\" style=\"left:52%;animation-delay:-1.1s\">clavier</span>\n        <span class=\"w\" style=\"left:30%;animation-delay:-2.2s\">écran</span>\n        <span class=\"w\" style=\"left:64%;animation-delay:-3.2s\">mail</span>\n        <div class=\"bar\"></div>\n        <div class=\"ground\"><span>FRAPPE-MOTS</span><span>SCORE <b class=\"score\">1 240</b></span></div>\n      </div></div>\n      <div class=\"pc-body\"><span class=\"pc-lab\">02 · Jeux</span><div class=\"pc-num\" data-to=\"12\">0<small>jeux</small></div><h3>S'entraîner en jouant</h3><p>Course, Duel 1v1, Battle Royale avec toute la classe : la vitesse vient en s'amusant.</p><span class=\"go\">Voir les jeux</span></div>\n    </a></div>\n\n    <div class=\"slot\"><a class=\"pc\" href=\"/cours-dactylo-en-ligne\" data-cta=\"pilier-modules\" style=\"--c:var(--blue);--tint:#EAF2FF\" data-anim=\"mail\">\n      <div class=\"pc-vis\"><div class=\"v-mail\">\n        <div class=\"dots\"><i></i><i></i><i></i></div>\n        <div class=\"f\">À : <b>stage@entreprise.be</b></div>\n        <div class=\"f\">Objet : <b>Candidature de stage</b></div>\n        <div class=\"body\"><span class=\"t\"></span><span class=\"cur\"></span></div>\n      </div><div class=\"v-chips\"><span class=\"on\">Mail</span><span>CV</span><span>Mot de passe</span><span>Raccourcis</span></div></div>\n      <div class=\"pc-body\"><span class=\"pc-lab\">03 · Compétences</span><div class=\"pc-num\" data-to=\"8\">0<small>modules</small></div><h3>Les bases du numérique</h3><p>Rédiger un mail, un CV, une lettre de motivation. Protéger ses comptes. Gagner du temps.</p><span class=\"go\">Voir les modules</span></div>\n    </a></div>\n\n    <div class=\"slot\"><a class=\"pc\" href=\"/test\" data-cta=\"pilier-test\" style=\"--c:var(--green);--tint:#E8F6EF\" data-anim=\"prog\">\n      <div class=\"pc-vis\"><div class=\"v-prog\">\n        <div class=\"top\"><div class=\"wpm\"><span class=\"n\">18</span><small>MOTS / MIN · EXEMPLE</small></div><span class=\"badge\">+36</span></div>\n        <svg viewBox=\"0 0 240 120\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n          <defs><linearGradient id=\"gArea\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#1FA971\" stop-opacity=\".28\"/><stop offset=\"1\" stop-color=\"#1FA971\" stop-opacity=\"0\"/></linearGradient></defs>\n          <g class=\"grid\"><line x1=\"0\" y1=\"30\" x2=\"240\" y2=\"30\"/><line x1=\"0\" y1=\"65\" x2=\"240\" y2=\"65\"/><line x1=\"0\" y1=\"100\" x2=\"240\" y2=\"100\"/></g>\n          <path class=\"area\" d=\"M4 108 C 30 104, 44 96, 62 92 S 96 86, 112 72 S 146 64, 162 50 S 200 30, 236 12 L236 120 L4 120Z\"/>\n          <path class=\"curve\" d=\"M4 108 C 30 104, 44 96, 62 92 S 96 86, 112 72 S 146 64, 162 50 S 200 30, 236 12\"/>\n        </svg>\n      </div></div>\n      <div class=\"pc-body\"><span class=\"pc-lab\">04 · Progrès</span><div class=\"pc-num\">1<small>minute pour se tester</small></div><h3>Mesurer son évolution</h3><p>Test de vitesse gratuit et illimité, historique et courbe de progression à chaque séance.</p><span class=\"go\">Faire le test</span></div>\n    </a></div>\n  </div>\n</div></div></section>\n\n<section class=\"trust\"><div class=\"wrap\">\n  <h2>Ils utilisent déjà KeyPace</h2>\n  <p class=\"sub\">Des établissements de tailles et de réseaux différents, du secondaire à l'administration communale.</p>\n</div>\n  <div class=\"trust-mask\"><div class=\"trust-row\" id=\"trust-row\"></div></div>\n</section>\n\n<section class=\"aud\" id=\"public\"><div class=\"wrap\">\n  <div class=\"sec-title\"><h2>Et vous, vous êtes ?</h2><p>KeyPace s'adapte à vos besoins.</p></div>\n  <div class=\"tabs\" role=\"tablist\">\n    <button class=\"on\" data-p=\"eleve\" style=\"--c:var(--accent)\"><i></i>Élève</button><button data-p=\"prof\" style=\"--c:var(--violet)\"><i></i>Enseignant</button><button data-p=\"ecole\" style=\"--c:var(--blue)\"><i></i>Établissement</button><button data-p=\"partenaire\" style=\"--c:var(--green)\"><i></i>Partenaire</button>\n  </div>\n\n  <!-- Élève -->\n  <div class=\"panel on\" id=\"p-eleve\" style=\"--pc:#FF4D2E;--pt:#FFF3EC\">\n    <div><span class=\"p-tag\">Pour les élèves</span><h3>Tape plus vite que tes potes. Écris mieux que tout le monde.</h3><p>Apprends à taper sans regarder, puis à écrire un vrai mail, un CV ou une lettre de motivation.</p>\n      <ul><li>10 premières leçons gratuites</li><li>Test de vitesse illimité</li><li>Duel 1v1 et Battle Royale avec ta classe</li></ul>\n      <div class=\"acts\"><a class=\"btn btn-pc\" href=\"/?auth=register\" data-cta=\"public-eleve\">Créer mon compte</a></div></div>\n    <div class=\"viz\">\n      <div class=\"shot\" style=\"left:28px;right:60px;top:60px\"><div class=\"bar\"><i></i><i></i><i></i></div><img src=\"/images/demo/demo-test.webp\" alt=\"Test de vitesse KeyPace\"></div>\n      <div class=\"float\" style=\"left:12px;top:14px\"><small>Ta vitesse</small><span class=\"big\">54</span> <b style=\"font-size:13px;color:var(--muted)\">mots/min</b><div class=\"xp\"><span></span></div></div>\n      <div class=\"float\" style=\"right:14px;top:120px\"><small>Duel 1v1</small><b>Gagné 🏆</b></div>\n      <div class=\"float\" style=\"left:40px;bottom:20px\"><small>Leçon 13</small><b>Débloquée ✓</b></div>\n      <img class=\"kiko\" src=\"/images/keypace-mascot-cheer.webp\" alt=\"\" style=\"right:8px;bottom:6px;width:120px\">\n    </div>\n  </div>\n\n  <!-- Enseignant -->\n  <div class=\"panel\" id=\"p-prof\" style=\"--pc:#6D5DF5;--pt:#F1EEFF\">\n    <div><span class=\"p-tag\">Pour les enseignants</span><h3>Votre cours de dactylo et de bureautique, déjà construit.</h3><p>Vous retrouvez vos classes, vous assignez, vous suivez. KeyPace fait le reste.</p>\n      <ul><li>Devoirs pour la classe ou pour quelques élèves</li><li>Copies de rédaction à corriger dans l'outil</li><li>Alertes : qui n'a pas commencé, qui bloque</li><li>Aligné sur le FMTTN (FWB) et le CRCN (France)</li></ul>\n      <div class=\"acts\"><a class=\"btn btn-pc\" href=\"/ecoles\" data-cta=\"public-prof\">Découvrir l'espace prof</a></div></div>\n    <div class=\"viz\">\n      <div class=\"shot\" style=\"left:40px;right:16px;top:70px;transform:rotate(1.5deg)\"><img src=\"/images/demo/demo-prof.webp\" alt=\"Tableau de bord professeur\"></div>\n      <div class=\"float\" style=\"left:12px;top:14px\"><small>Devoir envoyé</small><b>Rédiger un mail</b><div class=\"dots-av\"><i style=\"background:#FF4D2E\">AM</i><i style=\"background:#2F7DF6\">BV</i><i style=\"background:#1FA971\">CD</i><i style=\"background:#6D5DF5\">+21</i></div></div>\n      <div class=\"float\" style=\"right:12px;bottom:36px\"><small>À suivre</small><b><span style=\"color:#E5484D\">●</span> 3 élèves sous 80 %</b></div>\n      <img class=\"kiko\" src=\"/images/keypace-mascot-idea.webp\" alt=\"\" style=\"left:0;bottom:0;width:110px\">\n    </div>\n  </div>\n\n  <!-- Établissement -->\n  <div class=\"panel\" id=\"p-ecole\" style=\"--pc:#2F7DF6;--pt:#EDF4FF\">\n    <div><span class=\"p-tag\">Pour les établissements</span><h3>Une licence, toute l'école équipée.</h3><p>Vous nous envoyez vos listes d'élèves, nous créons les classes et les identifiants. Rien à installer, rien à configurer de votre côté.</p>\n      <ul><li>Toutes les leçons et tous les modules débloqués</li><li>Comptes élèves et professeurs</li><li>Éligible à la subvention MANOLO (FWB)</li><li>Conforme RGPD, données utilisées pour le seul suivi pédagogique</li></ul>\n      <div class=\"acts\"><a class=\"btn btn-pc\" href=\"/ecoles\" data-cta=\"public-ecole\">Découvrir l'offre écoles</a></div></div>\n    <div class=\"viz\">\n      <div class=\"school-ui\">\n        <div class=\"su-head\"><span class=\"ic\">É</span><div><b>Votre établissement</b><span>Espace école · licence active</span></div></div>\n        <div class=\"su-stats\"><div><b>12</b><span>classes</span></div><div><b>9</b><span>professeurs</span></div><div><b>264</b><span>élèves</span></div></div>\n        <div class=\"su-row\"><b>1re A</b><span>Mme Lambert · 24 élèves</span><div class=\"pb\"><i style=\"width:72%\"></i></div></div>\n        <div class=\"su-row\"><b>1re B</b><span>M. Dumont · 22 élèves</span><div class=\"pb\"><i style=\"width:58%\"></i></div></div>\n        <div class=\"su-row\"><b>2e C</b><span>Mme Leroy · 21 élèves</span><div class=\"pb\"><i style=\"width:84%\"></i></div></div>\n        <div class=\"su-row\"><b>5e qualif</b><span>M. Petit · 18 élèves</span><div class=\"pb\"><i style=\"width:41%\"></i></div></div>\n      </div>\n      <div class=\"float\" style=\"right:14px;bottom:14px\"><small>Subvention</small><b>MANOLO ✓</b></div>\n      <div class=\"float\" style=\"left:14px;bottom:24px\"><small>Données</small><b>🔒 RGPD</b></div>\n    </div>\n  </div>\n\n  <!-- Partenaire -->\n  <div class=\"panel\" id=\"p-partenaire\" style=\"--pc:#1FA971;--pt:#EAF7F0\">\n    <div><span class=\"p-tag\">Pour les partenaires</span><h3>Le chaînon manquant entre l'école et le numérique.</h3><p>Taper au clavier et écrire un mail sont des compétences attendues partout, et enseignées presque nulle part. KeyPace les rend enseignables, de la 3e primaire à la fin du secondaire.</p>\n      <ul><li>Pensé pour l'AZERTY belge et français</li><li>Complémentaire de Pix, pas concurrent</li><li>Déjà utilisé dans des écoles en Wallonie</li></ul>\n      <div class=\"acts\"><a class=\"btn btn-pc\" href=\"mailto:contact@keypace.be\" data-cta=\"public-partenaire\">Nous contacter</a></div></div>\n    <div class=\"viz\">\n      <div class=\"inv\">\n        <div style=\"--ic:#FF4D2E\"><b>66</b><span>leçons</span></div>\n        <div style=\"--ic:#6D5DF5\"><b>12</b><span>jeux</span></div>\n        <div style=\"--ic:#2F7DF6\"><b>8</b><span>modules</span></div>\n        <div style=\"--ic:#1FA971\"><b>BE · FR</b><span>référentiels couverts</span></div>\n      </div>\n      <div class=\"pilots-mini\"><small>Ils nous font confiance</small><div>\n        <img src=\"/images/partners/logo-isj.png\" alt=\"Institut Saint-Joseph Jambes\"><img src=\"/images/partners/logo-artamines.svg\" alt=\"Artamines\"><img src=\"/images/partners/logo-charleroi.png\" alt=\"Ville de Charleroi\"><img src=\"/images/partners/logo-stservais.jpg\" alt=\"Centre scolaire Asty-Moulin\"><img src=\"/images/partners/logo-iet.webp\" alt=\"IET Notre-Dame Charleroi\">\n      </div></div>\n    </div>\n  </div>\n</div></section>\n\n<section class=\"rev\" id=\"avis\">\n  <div class=\"wrap\"><div class=\"rev-head\">\n    <div class=\"eyebrow\">Avis</div>\n    <h2>Ce qu'ils en pensent</h2>\n    <div class=\"rev-score\"><b>5,0</b><div><div class=\"st\" aria-label=\"5 étoiles sur 5\">★★★★★</div><small>sur 19 avis</small></div></div>\n  </div></div>\n  <div class=\"rev-mask\"><div class=\"rev-row\" id=\"rev-row\"></div></div>\n</section>\n\n<section class=\"final\"><div class=\"wrap\">\n  <h2>Le clavier, <span>bien appris</span>, dès l'école.</h2>\n  <div class=\"hero-cta\"><a class=\"btn btn-accent\" href=\"/cours-dactylo-en-ligne\" data-cta=\"final-commencer\">Commencer gratuitement</a><a class=\"btn btn-ghost\" href=\"/ecoles\" data-cta=\"final-ecole\">Je représente une école</a></div>\n</div></section>";
function mount(host){
  var root=host.attachShadow({mode:'open'});
  root.innerHTML='<style>'+CSS+'</style><div class="lp">'+HTML+'</div>';
  /* Hauteur de l'en-tête collant de l'appli, pour la section qui reste épinglée au défilement. */
  var setNav=function(){var n=document.getElementById('main-nav');var p=n?getComputedStyle(n).position:'';host.style.setProperty('--nav-h',(n&&(p==='sticky'||p==='fixed')?n.offsetHeight:0)+'px')};
  setNav();window.addEventListener('resize',setNav);
  /* Rien ne tourne quand l'accueil n'est pas affiché (autre vue de l'appli, élève connecté). */
  var vis=function(){return host.isConnected&&host.offsetParent!==null};
  var setInterval=function(f,ms){return window.setInterval(function(){if(vis())f()},ms)};
  var addEventListener=function(t,f,o){window.addEventListener(t,function(e){if(vis())return f(e)},o)};
  /* Boutons : navigation de l'appli sans rechargement, suivi des clics. */
  var GO={'/cours-dactylo-en-ligne':'lessons','/jeux-dactylo-en-ligne':'games','/test':'testchoix'};
  root.addEventListener('click',function(e){var a=e.target.closest('a');if(!a)return;var h=a.getAttribute('href')||'';
    try{if(a.dataset.cta&&typeof track==='function')track('landing_cta',{cta:a.dataset.cta})}catch(x){}
    if(h==='/?auth=register'&&typeof openAuth==='function'){e.preventDefault();openAuth('register');return}
    if(GO[h]&&typeof go==='function'){e.preventDefault();go(GO[h]);window.scrollTo(0,0)}});

/* ---------- Bandeau des écoles : une seule rangée, boucle sans couture vers la droite ----------
   La rangée contient deux moitiés identiques, chacune plus large que l'écran. On la fait glisser de -50 % à 0 :
   à la fin, la position est exactement celle du début, donc aucun saut visible. */
(()=>{const L=[['logo-isj.png','Institut Saint-Joseph Jambes'],['logo-artamines.svg','Artamines'],['logo-charleroi.png','Ville de Charleroi',1],['logo-stservais.jpg','Centre scolaire Asty-Moulin'],['logo-iet.webp',"Institut d'Enseignement Technique Notre-Dame Charleroi",1]];
const row=root.getElementById('trust-row');
const set=hide=>L.map(([f,a,t])=>`<div class="logo-item${t?' tall':''}"${hide?' aria-hidden="true"':''}><img src="/images/partners/${f}" alt="${hide?'':a}"></div>`).join('');
async function build(){row.innerHTML=set(false);await Promise.all([...row.querySelectorAll('img')].map(i=>i.decode().catch(()=>{})));
  const w=row.scrollWidth,k=Math.max(1,Math.ceil(innerWidth/w)+1);let half=set(false);for(let n=1;n<k;n++)half+=set(true);
  row.innerHTML=half+half.replace(/<div class="logo-item([^"]*)"(?! aria)/g,'<div class="logo-item$1" aria-hidden="true"');
  row.style.setProperty('--dur',(k*w/45)+'s')}
build();let t;addEventListener('resize',()=>{clearTimeout(t);t=setTimeout(build,300)})})();

/* ---------- Avis ----------
   Mêmes avis que la page actuelle : les 5 avis Google publiables (prénom seul, accord reçu) + les avis publiés de /api/reviews.
   Mascotte : garçon (m) ou fille (f) fixée à la main par prénom ; prénom inconnu = les deux mascottes. Défilement sans couture. */
(()=>{const GOOGLE=[
  {n:'Rudy',s:'Google',t:"J'ai fait l'expérience d'un site très clair, dynamique et motivant dans l'apprentissage de la pratique du clavier et ses applications. À recommander +++"},
  {n:'Alexandre',s:'Google',t:"J'ai énormément appris en m'amusant !"},
  {n:'Baptiste',s:'Google',t:"Super projet ! Très simple d'utilisation."},
  {n:'Nora',s:'Google',t:"Super idée ! Très utile."},
  {n:'Marine',s:'Google',t:"Super site ! Les leçons sont adaptées à tous les niveaux et j'ai adoré les jeux !"}];
/* Avis publiés au 25/11/2026 : affichés tout de suite, remplacés par la réponse de l'API dès qu'elle arrive. */
const NATIFS=[
  {n:'Valentine',s:'KeyPace',t:"C'est trop bien d'avoir accès aux premières leçons gratuitement en plus les jeux sont vraiment addictifs ! Le site internet est super bien fait : il est intuitif et il t'explique vraiment bien ! 🤩"},
  {n:'Ahmed',s:'KeyPace',t:"outils très efficace pour apprendre à écrire plus vite très utile pour écrire de long texte rapidement"},
  {n:'Luna',s:'KeyPace',t:"Ludique et facile pour apprendre a tapper !"},
  {n:'Katelyne',s:'KeyPace',t:"Site très clair. Donne envie de continuer à faire les exercices. Très ludiques grâce aux différents jeux. Hâte de tout maîtriser."},
  {n:'Bryan',s:'KeyPace',t:"Super site, formation très complète qui m'a été recommandée par un collègue !"},
  {n:'Lucie',s:'KeyPace',t:"Site très prometteur pour apprendre à mieux taper sur un clavier ! Avec des cours ludiques et adaptés 😁"}];
const GENRE={Rudy:'m',Alexandre:'m',Baptiste:'m',Ahmed:'m',Bryan:'m',Nora:'f',Marine:'f',Valentine:'f',Luna:'f',Katelyne:'f',Lucie:'f'};
const POSE={m:[2,5,6,13,16],f:[3,8,9,11,12]},C=[['#FF4D2E','#FFF1EA'],['#6D5DF5','#F0EEFF'],['#2F7DF6','#EAF2FF'],['#1FA971','#E8F6EF']];
const esc=x=>String(x||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row=root.getElementById('rev-row');let used;
const card=(r,i,hide)=>{const g=GENRE[r.n],[c,t]=C[i%4],rot=[-1.6,1.2,-.8,1.6][i%4];
  const img=g?`/images/keypace-pose-${POSE[g][used[g]++%POSE[g].length]}.webp`:'/images/keypace-mascot-cheer.webp';
  return `<article class="rv" style="--c:${c};--t:${t};--r:${rot}deg"${hide?' aria-hidden="true"':''}><div class="rv-bubble"><div class="rv-stars">${'★'.repeat(r.r||5)}</div><p class="rv-txt">${esc(r.t)}</p></div>
  <div class="rv-foot"><div class="rv-kiko"><img src="${img}" alt="" loading="lazy"></div><div class="rv-who"><b>${esc(r.n)}</b><span>Avis ${r.s}</span></div></div></article>`};
/* Alterne Google et KeyPace pour varier les mascottes et les couleurs. */
const mix=(a,b)=>{const o=[];for(let i=0;i<Math.max(a.length,b.length);i++){if(a[i])o.push(a[i]);if(b[i])o.push(b[i])}return o};
function render(list,total,avg){const set=hide=>{used={m:0,f:0};return list.map((r,i)=>card(r,i,hide)).join('')};
  row.innerHTML=set(false)+set(true);row.style.setProperty('--dur',(row.scrollWidth/2/32)+'s');
  root.querySelector('.rev-score b').textContent=avg.toFixed(1).replace('.',',');root.querySelector('.rev-score small').textContent='sur '+total+' avis'}
render(mix(GOOGLE,NATIFS),19,5);
fetch('/api/reviews?action=list').then(r=>r.ok?r.json():null).then(d=>{if(!d||!d.count)return;
  const nat=(d.items||[]).filter(it=>it.show_card!==false&&it.comment).map(it=>({n:it.author_name,s:'KeyPace',t:it.comment,r:Math.round(it.rating||5)}));
  const seen=new Set(nat.map(x=>x.n));render(mix(GOOGLE.filter(g=>!seen.has(g.n)),nat).slice(0,14),Math.max(d.count,19),d.average||5)}).catch(()=>{})})();

/* ---------- Onglets « Et vous, vous êtes ? » ---------- */
root.querySelectorAll('.tabs button').forEach(b=>b.addEventListener('click',()=>{
  root.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('on',x===b));
  root.querySelectorAll('.panel').forEach(p=>p.classList.toggle('on',p.id==='p-'+b.dataset.p));
}));

/* ---------- Animations internes des cartes (lancées une fois la carte visible) ---------- */
const ANIMS={
  kb(card){const word=card.querySelector('.word'),keys={},ln=card.querySelector('.ln'),bar=card.querySelector('.lesson em');
    card.querySelectorAll('.kb span').forEach(s=>keys[s.textContent.toLowerCase()]=s);
    const W=['bonjour','clavier','sourire','maison'];let w=0,i=0,lesson=12;
    const draw=()=>{const s=W[w];word.innerHTML='<span class="ok">'+s.slice(0,i)+'</span>'+s.slice(i)};
    draw();setInterval(()=>{const s=W[w];if(i<s.length){const k=keys[s[i]];if(k){k.classList.add('hit');setTimeout(()=>k.classList.remove('hit'),170)}i++;draw()}else{i=0;w=(w+1)%W.length;lesson=lesson>=65?12:lesson+1;ln.textContent=lesson;bar.style.width=(lesson/66*100)+'%';draw()}},240)},
  fall(card){const sc=card.querySelector('.score');let v=1240;setInterval(()=>{v+=Math.round(40+Math.random()*60);sc.textContent=v.toLocaleString('fr-BE')},1050)},
  mail(card){const t=card.querySelector('.t'),chips=[...card.querySelectorAll('.v-chips span')];const T='Madame, Monsieur,\nje me permets de vous écrire pour vous proposer ma candidature.';let i=0,c=0;
    setInterval(()=>{if(i<T.length){i++;t.innerHTML=T.slice(0,i).replace('\n','<br>')}else if(i<T.length+25){i++}else{i=0;c=(c+1)%chips.length;chips.forEach((x,k)=>x.classList.toggle('on',k===c))}},55)},
  prog(card){const v=card.querySelector('.v-prog'),n=card.querySelector('.n'),b=card.querySelector('.badge');
    const run=()=>{v.classList.remove('run');b.classList.remove('on');n.textContent=18;void v.offsetWidth;v.classList.add('run');const t0=performance.now();
      const tick=t=>{const k=Math.min(1,(t-t0)/2600);n.textContent=Math.round(18+36*(1-Math.pow(1-k,3)));if(k<1)requestAnimationFrame(tick);else b.classList.add('on')};requestAnimationFrame(tick)};
    run();setInterval(run,6500)}
};
function countUp(card){const el=card.querySelector('.pc-num[data-to]');if(!el)return;const to=+el.dataset.to,sm=el.querySelector('small').outerHTML,t0=performance.now();
  const tick=t=>{const k=Math.min(1,(t-t0)/900);el.innerHTML=Math.round(to*(1-Math.pow(1-k,3)))+sm;if(k<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)}
function wake(card){if(card.dataset.live)return;card.dataset.live=1;card.classList.add('live');ANIMS[card.dataset.anim](card);countUp(card)}

/* ---------- Défilement immersif ----------
   La carte entre (glisse, se redresse, se défloute) puis prend le focus : elle se soulève, se colore,
   un halo de sa couleur glisse derrière elle et les autres s'effacent. À la fin, les quatre sont à égalité. */
(()=>{const sec=root.querySelector('.immerse'),slots=[...sec.querySelectorAll('.slot')],cards=slots.map(s=>s.querySelector('.pc')),
  titles=[...sec.querySelectorAll('.im-titles h2')],steps=[...sec.querySelectorAll('.im-steps b')],spot=sec.querySelector('.spot');
const COLORS=['#FF4D2E','#6D5DF5','#2F7DF6','#1FA971'];
const mq=matchMedia('(min-width:960px) and (min-height:640px) and (prefers-reduced-motion:no-preference)');
const clamp=v=>Math.max(0,Math.min(1,v)),ease=v=>1-Math.pow(1-v,3);
let io=null,cur=-2;
function setTitle(k){if(k===cur)return;cur=k;titles.forEach((h,j)=>h.classList.toggle('on',j===k))}
function frame(){if(!sec.classList.contains('pinned'))return;
  const total=sec.offsetHeight-innerHeight,p=clamp(-sec.getBoundingClientRect().top/total),FINAL=.86;
  let active=0,any=false;
  slots.forEach((s,i)=>{const st=.02+i*.2,e=ease(clamp((p-st)/.12)),tilt=(i%2?1:-1)*8;
    s.style.opacity=e;s.style.transform=`translateY(${(1-e)*180}px) rotate(${(1-e)*tilt}deg) scale(${.82+.18*e})`;s.style.filter=e<1?`blur(${(1-e)*10}px)`:'';
    if(e>.5){wake(cards[i]);active=i;any=true}});
  const fin=p>=FINAL;
  cards.forEach((c,i)=>{const entered=+slots[i].style.opacity>.98;c.classList.toggle('focus',!fin&&i===active&&entered);c.classList.toggle('dim',!fin&&entered&&i!==active)});
  steps.forEach((b,i)=>{b.classList.toggle('on',!fin&&i===active);b.classList.toggle('done',fin||i<active)});
  setTitle(fin?4:active);
  const s=slots[active];spot.style.left=(s.offsetLeft+s.offsetWidth/2)+'px';spot.style.backgroundColor=COLORS[active];spot.style.opacity=(any&&!fin)?.42:0;
}
function setMode(){
  if(mq.matches){sec.classList.add('pinned');if(io){io.disconnect();io=null}frame()}
  else{sec.classList.remove('pinned');slots.forEach(s=>s.removeAttribute('style'));cards.forEach(c=>c.classList.remove('focus','dim'));setTitle(4);
    io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');wake(e.target.querySelector('.pc'));io.unobserve(e.target)}}),{threshold:.25});slots.forEach(s=>io.observe(s))}
}
addEventListener('scroll',()=>requestAnimationFrame(frame),{passive:true});
addEventListener('resize',frame);mq.addEventListener('change',setMode);setMode();

/* Défilement ralenti : dans la section des piliers, la molette et le pavé tactile avancent moins vite
   (et chaque événement est plafonné), pour laisser le temps de lire chaque carte. Rien d'autre n'est modifié. */
const SLOW=.45,CAP=50;
addEventListener('wheel',e=>{if(!sec.classList.contains('pinned')||e.ctrlKey)return;
  const p=-sec.getBoundingClientRect().top/(sec.offsetHeight-innerHeight);if(p<0||p>=1)return;
  e.preventDefault();const d=e.deltaY*(e.deltaMode===1?16:1)*SLOW;
  scrollBy({top:Math.max(-CAP,Math.min(CAP,d)),behavior:'instant'})},{passive:false});
})();

}
window.KPLanding={mount:mount};
})();
